      const items = $$('.item', ul);
      const cur = items.indexOf(drag.li);
      const others = items.filter(x => x !== drag.li);
      let idx = 0;
      for (const o of others) {
        const r = o.getBoundingClientRect();
        if (e.clientY > r.top + r.height / 2) idx++;
      }
      if (idx !== cur) {
        drag.li.style.transform = 'none';
        if (idx < cur) ul.insertBefore(drag.li, items[idx]);
        else ul.insertBefore(drag.li, items[idx + 1]);
        drag.baseTop = drag.li.getBoundingClientRect().top;
      }
      drag.li.style.transform = `translateY(${(e.clientY - drag.offsetY) - drag.baseTop}px)`;
    };

