      if (!drag || (e.pointerId !== undefined && e.pointerId !== drag.id)) return;
      drag.li.classList.remove('is-dragging');
      ul.classList.remove('is-reordering');
      document.body.classList.remove('disc-drag');
      drag.li.style.transform = '';
      try { drag.li.releasePointerCapture(drag.id); } catch (_) {}
      drag = null;
    };

    ul.addEventListener('pointerdown', onDown);
    ul.addEventListener('pointermove', onMove);
    ul.addEventListener('pointerup', end);
    ul.addEventListener('pointercancel', end);
  }
